export class Subscribers {
  constructor() {
    this.subscribers = new Set();
    this.add = listener => {
      this.subscribers.add(listener);
      return () => this.subscribers.delete(listener);
    };
    this.emit = () => {
      for (const listener of this.subscribers) {
        listener();
      }
    };
    this.clear = () => {
      this.subscribers.clear();
    };
  }
}